{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Whole-person care</title>
  <meta name="description" content="{{BUSINESS_NAME}} blends modern insight and time-honored therapies to support wellbeing. Events, workshops, and patient-centered programs." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="zen">
  <header class="site-header">
    <div class="brand">
      <svg class="mark" viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#7AD3C7"/><stop offset="1" stop-color="#6B88FF"/></linearGradient></defs><rect x="6" y="6" width="52" height="52" rx="10" fill="url(#g1)"/><path d="M20 36c6-10 18-6 22-2" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>
      <div>
        <h1 class="business">{{BUSINESS_NAME}}</h1>
        <p class="tag">{{TAGLINE}}</p>
      </div>
    </div>

    <nav class="nav" id="nav">
      <button class="nav-toggle" id="navToggle" aria-expanded="false">Menu</button>
      <ul class="nav-list" id="navList">
        <li><a href="/">Home</a></li>
        <li><a href="services.html">Offerings</a></li>
        <li><a href="conditions.html">Concerns</a></li>
        <li><a href="approach.html">Method</a></li>
        <li><a href="pricing.html">Plans</a></li>
        <li><a href="book.html">Book</a></li>
      </ul>
    </nav>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="hero-inner">
        <h2 class="eyebrow">An integrative path to daily balance</h2>
        <h3 class="headline">Gentle assessments. Tailored plans. Practical rhythms.</h3>
        <p class="lead">We work with body, mind, and environment to help you build durable wellbeing. Education first — no promises, only careful support.</p>
        <div class="hero-cta">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="about.html">Meet {{PRACTITIONER_NAME}}</a>
        </div>
      </div>
      <svg class="hero-pattern" viewBox="0 0 800 200" preserveAspectRatio="none" aria-hidden="true"><use href="assets/img/pattern.svg#p1"/></svg>
    </section>

    <!-- DIAGNOSTIC -->
    <section class="diagnostic" id="diagnostic">
      <div class="wrap">
        <h4 class="section-title">A gentle diagnostic</h4>
        <p class="section-lead">We begin with listening: medical history, lifestyle, and guided questionnaires. Where appropriate, we suggest non-invasive labs for clarity — always as education and context for shared decisions.</p>

        <div class="grid">
          <div class="card">
            <h5>Intake conversation</h5>
            <p>Detailed review of symptoms, routines, and stressors to map priorities.</p>
          </div>
          <div class="card">
            <h5>Functional review</h5>
            <p>Systems-focused assessment: sleep, digestion, movement, mood, and energy.</p>
          </div>
          <div class="card">
            <h5>Optional labs</h5>
            <p>Selected lab work is explained and suggested only when it will change the plan.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PLAN -->
    <section class="plan" id="plan">
      <div class="wrap">
        <h4 class="section-title">A curated plan — small steps, clear aims</h4>
        <p class="section-lead">Plans focus on function and are revised over time. Each plan blends education, lifestyle changes, and targeted therapies to restore balance.</p>

        <div class="timeline">
          <div class="step">
            <div class="num">1</div>
            <div class="meta"><h6>Collaborative goal setting</h6><p>We pick a few measurable, meaningful goals together.</p></div>
          </div>
          <div class="step">
            <div class="num">2</div>
            <div class="meta"><h6>Personalized interventions</h6><p>Nutrition, movement, stress tools, and supportive therapies are combined safely.</p></div>
          </div>
          <div class="step">
            <div class="num">3</div>
            <div class="meta"><h6>Follow-ups</h6><p>Regular check-ins refine the plan based on outcomes and new insight.</p></div>
          </div>
        </div>
      </div>
    </section>

    <!-- MICRO HABITS -->
    <section class="micro-habits" id="micro_habits">
      <div class="wrap">
        <h4 class="section-title">Micro habits you can start today</h4>
        <p class="section-lead">Small, consistent practices accumulate into resilience. Choose one and practice it for two weeks.</p>
        <ul class="habits">
          <li><strong>2-minute breath break</strong> — pause twice daily and breathe slowly for 2 minutes.</li>
          <li><strong>Evening wind-down</strong> — dim lights and a 20-minute screen-free ritual before bed.</li>
          <li><strong>Plant-forward plate</strong> — add a colorful vegetable to one meal each day.</li>
        </ul>
        <p class="note">These suggestions are educational. They are not a substitute for medical advice.</p>
      </div>
    </section>

    <!-- PRICING (compact) -->
    <section class="pricing" id="pricing">
      <div class="wrap">
        <h4 class="section-title">Programs & events</h4>
        <p class="section-lead">Transparent options for one-off visits, short programs, and group workshops.</p>
        <div class="plans">
          <div class="plan-card">
            <h5>Intro Visit</h5>
            <p class="price">$120</p>
            <p class="desc">60-minute intake — history, priorities, and first steps.</p>
          </div>
          <div class="plan-card highlighted">
            <h5>Short Plan (6 weeks)</h5>
            <p class="price">$520</p>
            <p class="desc">Includes intake, two follow-ups, and written guidance.</p>
          </div>
          <div class="plan-card">
            <h5>Workshop series</h5>
            <p class="price">Varies</p>
            <p class="desc">Group events focused on sleep, stress, or digestion. Sliding scale available.</p>
          </div>
        </div>
        <p class="pricing-note">Note: Pricing and availability vary. Insurance may not cover integrative services.</p>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta" id="cta">
      <div class="wrap small">
        <h4>Ready to explore a whole-person approach?</h4>
        <p>Schedule a conversation — we prioritize education and shared decision-making.</p>
        <div class="cta-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="contact.html">Contact • {{PHONE}}</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <h5>{{BUSINESS_NAME}}</h5>
        <p class="muted">Holistic, integrative, and educational medicine in {{CITY}}, {{STATE}}.</p>
      </div>
      <div>
        <h6>Connect</h6>
        <p class="muted">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a><br/>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div>
        <h6>Practitioner</h6>
        <p class="muted">{{PRACTITIONER_NAME}}, {{CREDENTIALS}}</p>
      </div>
    </div>
    <div class="legal">© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved.</div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
