{"path":"assets/css/styles.css","content":"/* Zen minimal stylesheet — gradients, patterns, soft typography */
:root{
  --bg:#FBFDFC;
  --muted:#6b6f76;
  --accent1:#7AD3C7;
  --accent2:#6B88FF;
  --card:#ffffff;
  --radius:12px;
  --max:1100px;
  --shadow:0 6px 20px rgba(16,24,40,0.06);
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body.zen{margin:0;background:linear-gradient(180deg,var(--bg),#f4fbff 60%);color:#0b1020;line-height:1.5}
.wrap{max-width:var(--max);margin:0 auto;padding:48px 20px}
.small{padding:28px 20px}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:20px 24px;position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.7),rgba(255,255,255,0.45));backdrop-filter:blur(6px);z-index:40;border-bottom:1px solid rgba(10,12,18,0.04)}
.brand{display:flex;gap:14px;align-items:center}
.brand .mark{width:48px;height:48px}
.business{font-size:18px;margin:0}
.tag{margin:0;color:var(--muted);font-size:12px}
.nav{display:flex;align-items:center}
.nav-toggle{display:none;background:none;border:1px solid rgba(11,16,32,0.06);padding:8px 12px;border-radius:10px}
.nav-list{display:flex;gap:18px;list-style:none;margin:0;padding:0}
.nav-list a{color:inherit;text-decoration:none;font-size:15px}
.hero{position:relative;padding:80px 0 60px;background:linear-gradient(180deg,rgba(122,211,199,0.08),rgba(107,136,255,0.04));overflow:hidden}
.hero-inner{max-width:900px;margin:0 auto;padding:40px 20px}
.eyebrow{color:var(--accent1);margin:0 0 8px;font-weight:600}
.headline{font-size:28px;margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-cta .btn{margin-right:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:white;box-shadow:0 6px 18px rgba(107,136,255,0.12)}
.btn.ghost{background:transparent;border:1px solid rgba(11,16,32,0.06);color:var(--muted)}
.hero-pattern{position:absolute;right:-10%;bottom:-10%;width:60%;opacity:0.9}
.diagnostic{padding:40px 0}
.section-title{font-size:18px;margin:0 0 6px}
.section-lead{color:var(--muted);margin:0 0 20px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}
.card{background:var(--card);padding:18px;border-radius:var(--radius);box-shadow:var(--shadow)}
.timeline{display:grid;gap:12px}
.step{display:flex;gap:12px;align-items:flex-start}
.step .num{width:44px;height:44px;border-radius:10px;background:linear-gradient(180deg,var(--accent1),var(--accent2));color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700}
.micro-habits{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);padding:40px 0}
.habits{list-style:disc;margin:12px 0 0 20px;color:var(--muted)}
.note{font-size:13px;color:var(--muted);margin-top:10px}
.pricing{padding:40px 0}
.plans{display:flex;gap:14px;flex-wrap:wrap}
.plan-card{flex:1;min-width:220px;background:var(--card);padding:18px;border-radius:14px;box-shadow:var(--shadow)}
.plan-card.highlighted{border:1px solid rgba(107,136,255,0.14)}
.plan-card .price{font-size:20px;margin:8px 0}
.cta{padding:40px 0}
.cta .cta-actions{margin-top:12px}
.site-footer{padding:28px 0 40px;color:var(--muted);border-top:1px solid rgba(11,16,32,0.04);margin-top:40px}
.footer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}
.legal{text-align:center;font-size:13px;color:var(--muted);margin-top:18px}
@media(max-width:880px){
  .nav-list{display:none}
  .nav-toggle{display:inline-block}
  .wrap{padding:28px 16px}
  .hero-inner{padding:20px}
  .footer-grid{grid-template-columns:1fr}
}
/* Background use for the SVG pattern */
body::before{content:"";position:fixed;inset:0;z-index:-1;background-image:url('/assets/img/pattern.svg');opacity:0.06;mix-blend-mode:screen}
"}
{"path":"assets/js/main.js","content":"(function(){
  // Small interactions: nav toggle, current year, smooth scroll
  var navToggle=document.getElementById('navToggle');
  var navList=document.getElementById('navList');
  if(navToggle){
    navToggle.addEventListener('click',function(){
      var expanded = this.getAttribute('aria-expanded')==='true';
      this.setAttribute('aria-expanded', !expanded);
      if(navList){ navList.style.display = expanded ? 'none' : 'flex'; }
    });
  }

  // Set current year in footer
  var y = new Date().getFullYear();
  var el = document.getElementById('year');
  if(el) el.textContent = String(y);

  // Smooth scroll for local links
  document.addEventListener('click', function(e){
    var a = e.target.closest('a');
    if(!a) return;
    var href = a.getAttribute('href');
    if(href && href.startsWith('#')){
      e.preventDefault();
      var target = document.querySelector(href);
      if(target) target.scrollIntoView({behavior:'smooth'});
    }
  });

  // Lightweight form placeholder for booking link if present
  window.bookNow = function(){
    alert('Redirecting to booking — this is a placeholder.');
    window.location.href = '{{PRIMARY_CTA_URL}}';
  };
})();"} 
